escenas.Mundo:
// Mundo compartido: «Las ranuras de las monedas no son adorno».
// Mesa de taller antiguo con pared de tablas, estante, lámpara de aceite y libros.
// La moneda de plata grande está de pie sobre su canto en el centro.
// paso 0: moneda de canto liso, casi de frente; la mano con la lima ya apoyada en el borde.
// paso 1: moneda de canto liso, casi de frente (sin mano).
// paso 2: moneda girada de lado; se ve el canto liso.
// paso 3: moneda un poco más fina; papel doblado con polvillo plateado.
// paso 4: fila de monedas raspadas delante y lingote al fondo.
// paso 5: lo mismo, más una moneda intacta para comparar.
// paso 6: lo mismo, más la balanza (la intacta baja, la raspada sube).
// paso 7: moneda nueva con canto estriado; lingote al fondo.
// paso 8: moneda estriada con una franja raspada y lisa.
// paso 9: moneda estriada y busto de Newton sobre su pedestal; lingote.
// paso 10: prensa de recuñación con monedas viejas y nuevas; Newton observa.
// paso 11: moneda estriada de frente, moneda moderna lisa y un dedo en el canto.
import React from 'react';
import * as THREE from 'three';
import {Pieza, Brillo, Linea, Cartel, Mat, flotar} from '../lib3d';
import type {Paleta, V3} from '../lib3d';

export const PARTES = [
  'moneda', 'cantoliso', 'cantoestriado', 'franjaraspada', 'mano', 'lima', 'papel', 'polvillo',
  'lingote', 'fila', 'monedaintacta', 'sello', 'balanza', 'lupa', 'rodillos', 'newton', 'prensa',
  'monedalisa', 'dedo',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number; paso?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

export const TOP = 0.112; // superficie de la mesa (sobre el cuero)
export const R = 0.42; // radio de la moneda
export const G = 0.1; // grosor de la moneda
const PLATA = '#C9CFD7';
const PLATA_CLARA = '#EEF2F6';
const PLATA_OSC = '#8F98A3';
const PIEL = '#E9B793';
const LATON = '#C99A3A';
const HIERRO = '#3F4A4C';
const W_FRANJA = 0.36; // media anchura (rad) de la franja raspada

/** Pose de la moneda según el paso: posición, giro en Y y escala radial (raspada = más chica). */
export const poseMoneda = (paso: number) => {
  const k = paso >= 3 && paso <= 6 ? 0.95 : 1;
  const giro = paso <= 1 || paso >= 11 ? 0.35 : 1.05;
  return {x: 0, y: TOP + R * k, z: 0.15, giro, k};
};
/** Punto del canto que da a la cámara (ahí liman, tocan o pasan los rodillos). */
export const puntoCanto = (paso: number) => {
  const p = poseMoneda(paso);
  return {pos: [p.x - R * p.k * Math.cos(p.giro), p.y, p.z + R * p.k * Math.sin(p.giro)] as V3, giro: p.giro};
};
export const inclinacionBalanza = (paso: number) => (paso >= 6 ? 0.2 : 0);
export const cantoEstriado = (paso: number) => paso >= 7;

const col = (p: ParteProps, normal: string) => (p.resaltado ? p.paleta.acentos[2] : normal);

// Marco local de la moneda: el eje del cilindro (y local) apunta a la cara frontal.
const EnMoneda: React.FC<{paso?: number; children: React.ReactNode}> = ({paso = 0, children}) => {
  const p = poseMoneda(paso);
  return (
    <group position={[p.x, p.y, p.z]} rotation={[0, p.giro, 0]}>
      <group rotation={[Math.PI / 2, 0, 0]} scale={[p.k, 1, p.k]}>{children}</group>
    </group>
  );
};
// Marco local en el canto: -x hacia afuera, y hacia arriba, z como la cara de la moneda.
const EnCanto: React.FC<{paso?: number; children: React.ReactNode}> = ({paso = 0, children}) => {
  const c = puntoCanto(paso);
  return <group position={c.pos} rotation={[0, c.giro, 0]}>{children}</group>;
};

const estrias = (n: number, r: number, alto: number, color: string, saltar?: (a: number) => boolean) =>
  Array.from({length: n}, (_, i) => {
    const a = (i / n) * Math.PI * 2;
    if (saltar && saltar(a)) return null;
    return (
      <Pieza key={i} forma="caja" medidas={[(Math.PI * 2 * r) / n / 2, alto, 0.012]} color={color} contorno={false}
        posicion={[Math.cos(a) * r, 0, Math.sin(a) * r]} rotacion={[0, Math.PI / 2 - a, 0]} />
    );
  });

// ---------------- La moneda protagonista ----------------
export const Moneda: React.FC<ParteProps> = (p) => {
  const {frame = 0, paso = 0} = p;
  const c = col(p, PLATA);
  const rel = col(p, PLATA_CLARA);
  const a = frame / 22;
  const y = G / 2;
  return (
    <EnMoneda paso={paso}>
      <Pieza forma="cilindro" medidas={[R * 0.99, R * 0.99, G, 48]} color={c} />
      {[1, -1].map((s) => (
        <Pieza key={s} forma="toro" medidas={[R * 0.92, 0.022]} color={rel} posicion={[0, s * y, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      ))}
      <Pieza forma="cilindro" medidas={[0.2, 0.2, 0.014, 40]} color={rel} posicion={[0, y + 0.007, 0]} />
      {/* corona en relieve (z local negativa = arriba) */}
      <Pieza forma="caja" medidas={[0.2, 0.03, 0.06]} color={PLATA_OSC} posicion={[0, y + 0.02, 0.04]} />
      {[-0.07, 0, 0.07].map((x) => (
        <Pieza key={x} forma="esfera" medidas={[0.03]} color={PLATA_OSC} posicion={[x, y + 0.02, -0.02]} escala={[1, 0.5, 1]} />
      ))}
      <Pieza forma="caja" medidas={[0.016, 0.02, 0.055]} color={PLATA_OSC} posicion={[0, y + 0.02, -0.08]} />
      <Pieza forma="caja" medidas={[0.05, 0.02, 0.016]} color={PLATA_OSC} posicion={[0, y + 0.02, -0.085]} />
      {Array.from({length: 18}, (_, i) => {
        const b = (i / 18) * Math.PI * 2;
        return <Pieza key={i} forma="esfera" medidas={[0.013]} color={rel} contorno={false} posicion={[Math.cos(b) * 0.31, y + 0.004, Math.sin(b) * 0.31]} />;
      })}
      <Brillo posicion={[Math.cos(a) * R * 0.92, y + 0.03, Math.sin(a) * R * 0.92]} color="#FFFFFF" radio={0.016} />
    </EnMoneda>
  );
};

export const CantoLiso: React.FC<ParteProps> = (p) => (
  <EnMoneda paso={p.paso}>
    <Pieza forma="tubo" medidas={[R + 0.002, G * 0.98]} color={col(p, PLATA_CLARA)} />
  </EnMoneda>
);

/** Canto con ranuras. raspado 0..1: cuánto de la franja ya se borró (las estrías de esa zona desaparecen). */
export const CantoEstriado: React.FC<ParteProps & {raspado?: number}> = (p) => {
  const w = W_FRANJA * (p.raspado ?? 0);
  const saltar = (a: number) => w > 0 && Math.abs(a - Math.PI) < w;
  return (
    <EnMoneda paso={p.paso ?? 7}>
      <Pieza forma="tubo" medidas={[R + 0.001, G * 0.98]} color={col(p, PLATA_OSC)} />
      {estrias(72, R + 0.004, G * 0.9, col(p, PLATA_CLARA), saltar)}
    </EnMoneda>
  );
};

export const FranjaRaspada: React.FC<ParteProps> = (p) => {
  const c = col(p, '#B7BEC6');
  return (
    <EnMoneda paso={p.paso ?? 8}>
      <mesh castShadow>
        <cylinderGeometry args={[R + 0.011, R + 0.011, G * 0.96, 12, 1, true, -Math.PI / 2 - W_FRANJA, W_FRANJA * 2]} />
        <Mat color={c} />
      </mesh>
      {[-0.03, 0.004, 0.028].map((yy) => (
        <Pieza key={yy} forma="caja" medidas={[0.004, 0.004, 0.24]} color="#7E858E" contorno={false} posicion={[-(R + 0.013), yy, 0]} />
      ))}
    </EnMoneda>
  );
};

// ---------------- Mano, lima, dedo, lupa, rodillos (en el canto) ----------------
export const Lima: React.FC<ParteProps> = (p) => (
  <EnCanto paso={p.paso}>
    <Pieza forma="caja" medidas={[0.014, 0.5, 0.06]} color={col(p, '#6F757D')} posicion={[-0.012, 0.02, 0]} />
    <Pieza forma="caja" medidas={[0.016, 0.44, 0.02]} color="#9AA0A8" contorno={false} posicion={[-0.012, 0.0, 0]} />
    <Pieza forma="cilindro" medidas={[0.036, 0.036, 0.03]} color={LATON} posicion={[-0.012, 0.28, 0]} />
    <Pieza forma="cilindro" medidas={[0.03, 0.036, 0.22]} color="#8B5A2B" posicion={[-0.012, 0.4, 0]} />
  </EnCanto>
);

export const Mano: React.FC<ParteProps> = (p) => {
  const piel = col(p, PIEL);
  return (
    <EnCanto paso={p.paso}>
      <group position={[-0.06, 0.4, 0]} scale={1.3}>
        <Pieza forma="esfera" medidas={[0.075]} color={piel} escala={[1.1, 1.25, 1]} posicion={[-0.03, 0, -0.01]} />
        {[0, 1, 2, 3].map((i) => (
          <Pieza key={i} forma="capsula" medidas={[0.022, 0.05]} color={piel} posicion={[0.03, -0.055 + i * 0.037, 0.045]} rotacion={[0, 0, Math.PI / 2]} />
        ))}
        <Pieza forma="capsula" medidas={[0.022, 0.05]} color={piel} posicion={[0.01, 0.07, -0.045]} rotacion={[0.3, 0, 0.5]} />
        <group position={[-0.04, 0.04, 0]} rotation={[0, 0, 0.9]}>
          <Pieza forma="toro" medidas={[0.07, 0.02]} color="#F3EEE4" posicion={[0, 0.07, 0]} rotacion={[Math.PI / 2, 0, 0]} />
          <Pieza forma="cilindro" medidas={[0.075, 0.085, 0.42]} color="#6A4B8C" posicion={[0, 0.28, 0]} />
        </group>
      </group>
    </EnCanto>
  );
};

export const Dedo: React.FC<ParteProps> = (p) => {
  const piel = col(p, PIEL);
  return (
    <EnCanto paso={p.paso ?? 11}>
      <Pieza forma="capsula" medidas={[0.03, 0.15]} color={piel} posicion={[-0.12, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
      <Pieza forma="caja" medidas={[0.04, 0.008, 0.035]} color="#F4D3C0" posicion={[-0.05, 0.03, 0]} />
      <Pieza forma="esfera" medidas={[0.08]} color={piel} posicion={[-0.29, -0.02, 0]} escala={[1.3, 0.85, 1]} />
      {[-0.035, 0, 0.035].map((z) => (
        <Pieza key={z} forma="esfera" medidas={[0.03]} color={piel} posicion={[-0.22, -0.07, z]} />
      ))}
      <group position={[-0.36, -0.03, 0]} rotation={[0, 0, 1.8]}>
        <Pieza forma="cilindro" medidas={[0.07, 0.08, 0.4]} color="#2F5D7C" posicion={[0, 0.25, 0]} />
      </group>
    </EnCanto>
  );
};

export const Lupa: React.FC<ParteProps> = (p) => (
  <EnCanto paso={p.paso ?? 5}>
    <group position={[-0.3, 0.12, 0.12]} rotation={[0, Math.PI / 2, 0.3]}>
      <Pieza forma="toro" medidas={[0.11, 0.014]} color={col(p, LATON)} />
      <Pieza forma="cilindro" medidas={[0.105, 0.105, 0.006]} color="#CFE6F2" opacidad={0.3} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
      <Pieza forma="cilindro" medidas={[0.018, 0.024, 0.2]} color="#2A2320" posicion={[0, -0.21, 0]} />
    </group>
  </EnCanto>
);

export const Rodillos: React.FC<ParteProps> = (p) => {
  const giro = (p.frame ?? 0) / 8;
  return (
    <EnCanto paso={p.paso ?? 6}>
      <group position={[-0.09, 0, 0]} rotation={[Math.PI / 2, giro, 0]}>
        <Pieza forma="cilindro" medidas={[0.075, 0.075, 0.16]} color={col(p, '#A9AFB6')} />
        {estrias(18, 0.077, 0.15, '#6D747C')}
      </group>
      <Pieza forma="caja" medidas={[0.07, 0.3, 0.28]} color={HIERRO} posicion={[-0.21, 0, 0]} />
      <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.36]} color={LATON} posicion={[-0.13, 0, 0]} rotacion={[Math.PI / 2, 0, 0]} />
      <Pieza forma="caja" medidas={[0.03, 0.18, 0.03]} color={HIERRO} posicion={[-0.13, 0.08, 0.2]} />
      <Pieza forma="esfera" medidas={[0.03]} color="#7A2E22" posicion={[-0.13, 0.17, 0.2]} />
    </EnCanto>
  );
};

// ---------------- Monedas chicas, papel, polvillo, lingote ----------------
const MonedaChica: React.FC<{pos: V3; r: number; color: string; estriada?: boolean}> = ({pos, r, color, estriada}) => (
  <group position={pos}>
    <Pieza forma="cilindro" medidas={[r, r, 0.026, 36]} color={color} posicion={[0, 0.013, 0]} />
    <Pieza forma="toro" medidas={[r * 0.86, 0.007]} color={PLATA_CLARA} posicion={[0, 0.026, 0]} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
    <Pieza forma="cilindro" medidas={[r * 0.45, r * 0.45, 0.006]} color={PLATA_CLARA} posicion={[0, 0.028, 0]} contorno={false} />
    {estriada ? <group position={[0, 0.013, 0]}>{estrias(30, r + 0.003, 0.022, PLATA_CLARA)}</group> : null}
  </group>
);

export const Papel: React.FC<ParteProps> = (p) => (
  <group position={[-0.42, TOP, 0.58]} rotation={[0, 0.25, 0]}>
    {[-1, 1].map((s) => (
      <Pieza key={s} forma="caja" medidas={[0.24, 0.004, 0.34]} color={col(p, '#F1E8D6')} posicion={[s * 0.117, 0.014, 0]} rotacion={[0, 0, s * 0.12]} />
    ))}
  </group>
);

export const Polvillo: React.FC<ParteProps> = (p) => {
  const c = col(p, PLATA);
  return (
    <group position={[-0.42, TOP + 0.004, 0.58]}>
      <Pieza forma="media_esfera" medidas={[0.07]} color={c} escala={[1, 0.35, 1]} />
      {Array.from({length: 9}, (_, i) => {
        const h = Math.sin(i * 12.9898) * 43758.5453;
        const r = h - Math.floor(h);
        const a = i * 2.4;
        return <Pieza key={i} forma="esfera" medidas={[0.008 + r * 0.006]} color={PLATA_CLARA} contorno={false} posicion={[Math.cos(a) * (0.08 + r * 0.06), 0.006, Math.sin(a) * (0.06 + r * 0.05)]} />;
      })}
      <Brillo posicion={[0.01, 0.03 + flotar(p.frame ?? 0, 0.005, 40), 0]} color="#FFFFFF" radio={0.01} />
    </group>
  );
};

export const Lingote: React.FC<ParteProps> = (p) => {
  const c = col(p, PLATA_CLARA);
  const f = p.frame ?? 0;
  return (
    <group position={[0.55, TOP, -0.5]} rotation={[0, -0.35, 0]}>
      <Pieza forma="caja" medidas={[0.28, 0.07, 0.13]} color={c} posicion={[0, 0.035, 0]} />
      <Pieza forma="caja" medidas={[0.23, 0.02, 0.09]} color={c} posicion={[0, 0.08, 0]} />
      <Brillo posicion={[-0.1 + ((f % 90) / 90) * 0.2, 0.092, 0.03]} color="#FFFFFF" radio={0.012} />
    </group>
  );
};

export const Fila: React.FC<ParteProps> = (p) => (
  <group>
    {[-0.8, -0.55, -0.3, -0.05].map((x, i) => (
      <MonedaChica key={i} pos={[x, TOP, 0.72 - i * 0.02]} r={0.105} color={col(p, PLATA)} />
    ))}
  </group>
);

export const MonedaIntacta: React.FC<ParteProps> = (p) => <MonedaChica pos={[0.3, TOP, 0.7]} r={0.125} color={col(p, PLATA)} />;

export const MonedaLisa: React.FC<ParteProps> = (p) => (
  <group position={[0.62, TOP, 0.5]}>
    <Pieza forma="cilindro" medidas={[0.13, 0.13, 0.028, 36]} color={col(p, '#D9B24A')} posicion={[0, 0.014, 0]} />
    <Pieza forma="toro" medidas={[0.11, 0.008]} color="#F0D27A" posicion={[0, 0.028, 0]} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
    <Pieza forma="cilindro" medidas={[0.05, 0.05, 0.006]} color="#F0D27A" posicion={[0, 0.03, 0]} contorno={false} />
  </group>
);

export const Sello: React.FC<ParteProps> = (p) => (
  <group position={[0.68, TOP, 0.28]}>
    <Pieza forma="caja" medidas={[0.24, 0.04, 0.15]} color={col(p, p.paleta.acentos[0])} posicion={[0, 0.02, 0]} />
    <Pieza forma="caja" medidas={[0.22, 0.05, 0.13]} color="#8B5A2B" posicion={[0, 0.065, 0]} />
    <Pieza forma="cilindro" medidas={[0.025, 0.035, 0.14]} color="#6B4226" posicion={[0, 0.16, 0]} />
    <Pieza forma="esfera" medidas={[0.05]} color="#6B4226" posicion={[0, 0.25, 0]} />
    <Cartel texto="RECORTE" posicion={[0, 0.42, 0]} alto={0.12} fondo={p.paleta.acentos[0]} colorTexto="#FFFFFF" />
  </group>
);

// ---------------- Balanza, Newton, prensa ----------------
export const Balanza: React.FC<ParteProps & {inclinacion?: number}> = (p) => {
  const t = p.inclinacion ?? inclinacionBalanza(p.paso ?? 6);
  const metal = col(p, LATON);
  return (
    <group position={[-0.82, TOP, -0.2]}>
      <Pieza forma="caja" medidas={[0.34, 0.04, 0.2]} color="#6B4226" posicion={[0, 0.02, 0]} />
      <Pieza forma="cilindro" medidas={[0.022, 0.03, 0.6]} color={metal} posicion={[0, 0.32, 0]} />
      <Pieza forma="esfera" medidas={[0.03]} color={metal} posicion={[0, 0.65, 0]} />
      <group position={[0, 0.62, 0]} rotation={[0, 0, t]}>
        <Pieza forma="caja" medidas={[0.62, 0.025, 0.03]} color={metal} />
        <Pieza forma="cono" medidas={[0.015, 0.12]} color={metal} posicion={[0, -0.07, 0.02]} rotacion={[Math.PI, 0, 0]} />
      </group>
      {[-1, 1].map((s) => {
        const ex = s * 0.29 * Math.cos(t);
        const ey = 0.62 + s * 0.29 * Math.sin(t);
        return (
          <group key={s}>
            {[-0.07, 0.07].map((dx) => (
              <Linea key={dx} desde={[ex, ey, 0]} hasta={[ex + dx, ey - 0.24, 0]} grosor={0.004} color="#3A3A3A" />
            ))}
            <Pieza forma="cilindro" medidas={[0.1, 0.07, 0.02]} color={metal} posicion={[ex, ey - 0.25, 0]} />
            <MonedaChica pos={[ex, ey - 0.24, 0]} r={s < 0 ? 0.085 : 0.075} color={PLATA} />
          </group>
        );
      })}
    </group>
  );
};

export const Newton: React.FC<ParteProps> = (p) => {
  const peluca = col(p, '#F4F1EA');
  return (
    <group position={[-0.78, TOP, -0.3]} rotation={[0, 0.35, 0]}>
      <Pieza forma="caja" medidas={[0.3, 0.06, 0.3]} color="#D8D0C2" posicion={[0, 0.03, 0]} />
      <Pieza forma="cilindro" medidas={[0.11, 0.13, 0.26]} color="#E6E0D4" posicion={[0, 0.19, 0]} />
      <Pieza forma="caja" medidas={[0.28, 0.04, 0.28]} color="#D8D0C2" posicion={[0, 0.34, 0]} />
      <Cartel texto="NEWTON" posicion={[0, 0.19, 0.135]} alto={0.045} fondo={p.paleta.acentos[3]} colorTexto="#1B1B1F" rotacion={[0, 0.0001, 0]} />
      <Pieza forma="media_esfera" medidas={[0.16]} color={col(p, '#5B2E2A')} posicion={[0, 0.36, 0]} escala={[1.2, 0.85, 0.75]} />
      <Pieza forma="caja" medidas={[0.06, 0.09, 0.03]} color="#FFFFFF" posicion={[0, 0.45, 0.1]} />
      <Pieza forma="cilindro" medidas={[0.04, 0.045, 0.08]} color={PIEL} posicion={[0, 0.5, 0]} />
      <Pieza forma="esfera" medidas={[0.09]} color={PIEL} posicion={[0, 0.6, 0]} />
      <Pieza forma="cono" medidas={[0.014, 0.04]} color={PIEL} posicion={[0, 0.59, 0.095]} rotacion={[Math.PI / 2, 0, 0]} />
      {[-1, 1].map((s) => (
        <group key={s}>
          <Pieza forma="esfera" medidas={[0.01]} color="#1B1B1F" contorno={false} posicion={[s * 0.032, 0.615, 0.083]} />
          {[0.58, 0.51, 0.44].map((y, i) => (
            <Pieza key={y} forma="esfera" medidas={[0.05 - i * 0.004]} color={peluca} posicion={[s * (0.1 + i * 0.01), y, -0.01]} />
          ))}
        </group>
      ))}
      <Pieza forma="media_esfera" medidas={[0.104]} color={peluca} posicion={[0, 0.615, -0.005]} escala={[1.05, 0.9, 1.05]} />
      <Pieza forma="esfera" medidas={[0.085]} color={peluca} posicion={[0, 0.53, -0.07]} />
    </group>
  );
};

export const Prensa: React.FC<ParteProps> = (p) => {
  const hierro = col(p, HIERRO);
  const giro = flotar(p.frame ?? 0, 0.25, 90);
  return (
    <group position={[0.72, TOP, -0.4]} rotation={[0, -0.3, 0]}>
      <Pieza forma="caja" medidas={[0.5, 0.06, 0.3]} color={hierro} posicion={[0, 0.03, 0]} />
      {[-0.18, 0.18].map((x) => (
        <Pieza key={x} forma="cilindro" medidas={[0.03, 0.03, 0.6]} color={hierro} posicion={[x, 0.36, 0]} />
      ))}
      <Pieza forma="caja" medidas={[0.46, 0.08, 0.12]} color={hierro} posicion={[0, 0.68, 0]} />
      <Pieza forma="cilindro" medidas={[0.025, 0.025, 0.36]} color={LATON} posicion={[0, 0.54, 0]} />
      <Pieza forma="caja" medidas={[0.16, 0.06, 0.14]} color="#5C6668" posicion={[0, 0.34, 0]} />
      <Pieza forma="cilindro" medidas={[0.07, 0.07, 0.05]} color="#A9AFB6" posicion={[0, 0.085, 0]} />
      <group position={[0, 0.77, 0]} rotation={[0, giro, 0]}>
        <Pieza forma="cilindro" medidas={[0.014, 0.014, 0.6]} color={LATON} rotacion={[0, 0, Math.PI / 2]} />
        {[-0.3, 0.3].map((x) => (
          <Pieza key={x} forma="esfera" medidas={[0.035]} color="#7A2E22" posicion={[x, 0, 0]} />
        ))}
      </group>
      {[0, 1, 2, 3].map((i) => (
        <group key={i}>
          <MonedaChica pos={[-0.36 + (i % 2) * 0.01, 0.026 * i, 0.03]} r={0.06} color="#A8A79F" />
          <MonedaChica pos={[0.36, 0.026 * i, 0.03]} r={0.065} color={PLATA} estriada />
        </group>
      ))}
    </group>
  );
};

// ---------------- El taller (fondo fijo) ----------------
const Taller: React.FC<{frame: number}> = ({frame}) => {
  const llama = 0.9 + Math.sin(frame / 3) * 0.08 + Math.sin(frame / 7.3) * 0.05;
  return (
    <group>
      <Pieza forma="caja" medidas={[2.5, 0.1, 1.9]} color="#9A6A3C" posicion={[0, 0.05, -0.05]} />
