        <Pieza key={z} forma="caja" medidas={[2.48, 0.004, 0.008]} color="#7A5130" contorno={false} posicion={[0, 0.101, z]} />
      ))}
      <Pieza forma="caja" medidas={[1.6, 0.012, 1.05]} color="#5C4636" posicion={[0, 0.106, 0.25]} />
      {/* pared de tablas */}
      {[0, 1, 2, 3, 4, 5].map((i) => (
        <Pieza key={i} forma="caja" medidas={[0.41, 1.85, 0.05]} color={i % 2 ? '#C9B597' : '#BFA987'} posicion={[-1.025 + i * 0.41, 0.925, -1.0]} />
