      ))}
      {[
        [-0.9, '#8A5A2B', 0.16],
        [-0.7, '#6E8B5E', 0.22],
        [-0.48, '#C67B4E', 0.13],
      ].map(([x, c, h]) => (
        <group key={x as number} position={[x as number, 1.47, -0.86]}>
          <Pieza forma="cilindro" medidas={[0.06, 0.06, h as number]} color={c as string} posicion={[0, (h as number) / 2, 0]} />
          <Pieza forma="cilindro" medidas={[0.045, 0.045, 0.03]} color="#3A2A1E" posicion={[0, (h as number) + 0.015, 0]} />
        </group>
      ))}
      <Pieza forma="caja" medidas={[0.2, 0.12, 0.14]} color="#A0522D" posicion={[-0.25, 1.53, -0.87]} />
      {/* herramientas colgadas */}
      <group position={[0.55, 1.2, -0.96]} rotation={[0, 0, 0.2]}>
        <Pieza forma="caja" medidas={[0.04, 0.38, 0.03]} color="#8B5A2B" />
        <Pieza forma="caja" medidas={[0.17, 0.055, 0.05]} color={HIERRO} posicion={[0, 0.2, 0]} />
      </group>
      <Pieza forma="caja" medidas={[0.06, 0.62, 0.012]} color="#E0C27A" posicion={[0.92, 1.12, -0.97]} />
      {[0.55, 0.92].map((x) => (
        <Pieza key={x} forma="cilindro" medidas={[0.012, 0.012, 0.06]} color={LATON} posicion={[x, 1.46, -0.95]} rotacion={[Math.PI / 2, 0, 0]} />
      ))}
      {/* lámpara de aceite */}
      <group position={[-0.95, TOP, -0.62]}>
        <Pieza forma="cilindro" medidas={[0.07, 0.09, 0.03]} color={LATON} posicion={[0, 0.015, 0]} />
        <Pieza forma="esfera" medidas={[0.08]} color={LATON} posicion={[0, 0.1, 0]} escala={[1, 0.75, 1]} />
        <Pieza forma="cilindro" medidas={[0.04, 0.055, 0.2]} color="#F4EEDD" opacidad={0.35} posicion={[0, 0.25, 0]} />
        <group scale={[1, llama, 1]} position={[0, 0.2, 0]}>
          <Brillo posicion={[0, 0.02, 0]} color="#FFB347" radio={0.018} luz={0.5 * llama} />
        </group>
      </group>
      {/* libros */}
      {['#7D2E2A', '#2F4A5E', '#6B5A3A'].map((c, i) => (
        <Pieza key={c} forma="caja" medidas={[0.3 - i * 0.03, 0.055, 0.22]} color={c} posicion={[0.95, TOP + 0.028 + i * 0.056, -0.72]} rotacion={[0, 0.15 * (i - 1), 0]} />
      ))}
      <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.3]} color="#E0A526" posicion={[0.82, TOP + 0.012, 0.68]} rotacion={[0, 0.6, Math.PI / 2]} />
    </group>
  );
};

// ---------------- El mundo según el paso ----------------
export const Mundo: React.FC<MundoProps> = (props) => {
  const {paso, frame, paleta, ocultar = [], resaltar = []} = props;
  const ver = (n: string) => !ocultar.includes(n);
  const p = (n: string): ParteProps => ({paleta, frame, paso, resaltado: resaltar.includes(n)});
  const entre = (a: number, b: number) => paso >= a && paso <= b;
  const estriada = cantoEstriado(paso);
  return (
    <group>
      <Taller frame={frame} />
      {ver('moneda') ? <Moneda {...p('moneda')} /> : null}
      {!estriada && ver('cantoliso') ? <CantoLiso {...p('cantoliso')} /> : null}
      {estriada && ver('cantoestriado') ? <CantoEstriado {...p('cantoestriado')} raspado={paso === 8 ? 1 : 0} /> : null}
      {paso === 8 && ver('franjaraspada') ? <FranjaRaspada {...p('franjaraspada')} /> : null}
      {paso === 0 && ver('lima') ? <Lima {...p('lima')} /> : null}
      {paso === 0 && ver('mano') ? <Mano {...p('mano')} /> : null}
      {paso === 3 && ver('papel') ? <Papel {...p('papel')} /> : null}
      {paso === 3 && ver('polvillo') ? <Polvillo {...p('polvillo')} /> : null}
      {entre(4, 9) && ver('lingote') ? <Lingote {...p('lingote')} /> : null}
      {entre(4, 6) && ver('fila') ? <Fila {...p('fila')} /> : null}
      {entre(5, 6) && ver('monedaintacta') ? <MonedaIntacta {...p('monedaintacta')} /> : null}
      {paso === 6 && ver('balanza') ? <Balanza {...p('balanza')} /> : null}
      {entre(9, 10) && ver('newton') ? <Newton {...p('newton')} /> : null}
      {paso === 10 && ver('prensa') ? <Prensa {...p('prensa')} /> : null}
      {paso === 11 && ver('monedalisa') ? <MonedaLisa {...p('monedalisa')} /> : null}
      {paso === 11 && ver('dedo') ? <Dedo {...p('dedo')} /> : null}
    </group>
  );
};

// Para escenas que necesiten el material del canal fuera de Pieza.
export const geometriaFranja = () => new THREE.CylinderGeometry(R + 0.011, R + 0.011, G * 0.96, 12, 1, true, -Math.PI / 2 - W_FRANJA, W_FRANJA * 2);

