// Escena 2: «Mira esta moneda de plata. Su canto es completamente liso.»
// La moneda gira de casi frente (paso 1) a de lado (paso 2) y un destello recorre su canto liso.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Etiqueta, Brillo, aparecer, momento} from '../lib3d';
import {Mundo, Moneda, CantoLiso, poseMoneda, R, G} from './Mundo';

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];
  const extra = paleta.acentos[3];

  // Golpes con la voz
  const tMira = momento(palabras, fps, 'mira', 1);
  const tMoneda = momento(palabras, fps, 'moneda', 19);
  const tPlata = momento(palabras, fps, 'plata', 35);
  const tSu = momento(palabras, fps, 'su', 62);
  const tCanto = momento(palabras, fps, 'canto', 67);
  const tComp = momento(palabras, fps, 'completamente', 86);
  const tLiso = momento(palabras, fps, 'liso', 108);
  const fin = duracion;

  // Pose: de paso 1 a paso 2 (mismo centro, mismo tamaño, solo cambia el giro)
  const p1 = poseMoneda(1);
  const p2 = poseMoneda(2);
  const C: [number, number, number] = [p1.x, p1.y, p1.z];
  const giroIni = tSu - 14;
  const d = interpolate(frame, [giroIni, giroIni + 26], [0, p2.giro - p1.giro], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.inOut(Easing.cubic),
  });
  // Pequeño saltito al decir "mira" (vuelve exacto a la mesa)
  const fs = frame - tMira;
  const salto = fs >= 0 && fs <= 10 ? Math.sin((fs / 10) * Math.PI) * 0.05 : 0;
  // Leve balanceo al terminar de girar (se apaga antes de la mitad de la escena siguiente)
  const fb = frame - (giroIni + 26);
  const balanceo = fb > 0 ? Math.exp(-fb / 6) * Math.sin(fb / 1.8) * 0.05 : 0;

  // Resaltes
  const cantoResaltado = frame >= tCanto && frame < tCanto + 40;
  const monedaBrilla = frame >= tMoneda && frame < tMoneda + 14;
  const reflejo = interpolate(frame, [tMoneda, tMoneda + 14], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

  // Arco punteado que rodea el borde y destello que lo recorre
  const salida = interpolate(frame, [fin - 12, fin - 2], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const arco = interpolate(frame, [tComp, tLiso], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'}) * (salida > 0 ? 1 : 0);
  const nDash = 36;
  const destello = interpolate(frame, [tLiso - 4, tLiso + 32], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const destelloVis = frame >= tLiso - 4 && frame <= tLiso + 34;
  const aD = Math.PI + destello * Math.PI * 2; // empieza en el canto que da a la cámara

  // Textos (en coordenadas del mundo, ya con la moneda de lado)
  const g2 = p2.giro;
  const puntoCanto: [number, number, number] = [C[0] - R * Math.cos(g2), C[1] + 0.05, C[2] + R * Math.sin(g2)];
  const plataVis = aparecer(frame, tPlata, 8) * interpolate(frame, [tSu - 2, tSu + 6], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const lisoVis = aparecer(frame, tLiso, 8) * salida;

  return (
    <group>
      <Mundo paso={1} frame={frame} fps={fps} paleta={paleta} ocultar={['moneda', 'cantoliso']} />

      {/* La moneda protagonista girando sobre su propio centro */}
      <group position={[C[0], C[1] + salto, C[2]]} rotation={[0, d, balanceo]}>
        <group position={[-C[0], -C[1], -C[2]]}>
          <Moneda paleta={paleta} frame={frame} paso={1} resaltado={monedaBrilla && frame < tMoneda + 4} />
          <CantoLiso paleta={paleta} frame={frame} paso={1} resaltado={cantoResaltado} />
        </group>

        {/* Marco local de la moneda: cara hacia +z, borde en el plano x-y */}
        <group rotation={[0, p1.giro, 0]}>
          {/* reflejo que cruza la cara al decir "moneda" */}
          {monedaBrilla ? (
            <group position={[interpolate(reflejo, [0, 1], [-0.32, 0.32]), interpolate(reflejo, [0, 1], [0.3, -0.3]), G / 2 + 0.03]} rotation={[0, 0, Math.PI / 4]}>
              <Pieza forma="caja" medidas={[0.05, 0.5, 0.004]} color="#FFFFFF" brillo="#FFFFFF" opacidad={0.6} contorno={false} />
              <Brillo posicion={[0, 0, 0.01]} color="#FFFFFF" radio={0.03} />
            </group>
          ) : null}

          {/* arco punteado alrededor del canto */}
          {Array.from({length: nDash}, (_, i) => {
            if (i >= Math.floor(arco * nDash) || arco <= 0) return null;
            const a = Math.PI - (i / nDash) * Math.PI * 2;
            const rr = R + 0.07;
            return (
              <Pieza key={i} forma="caja" medidas={[0.018, 0.04, 0.018]} color={resalte} brillo={resalte} intensidadBrillo={0.4}
                contorno={false} posicion={[Math.cos(a) * rr, Math.sin(a) * rr, 0]} rotacion={[0, 0, a]} escala={salida} />
            );
          })}

          {/* destello que recorre todo el borde */}
          {destelloVis
            ? [0, 1, 2, 3].map((k) => {
                const a = aD - k * 0.12;
                const rr = R + 0.012;
                return (
                  <Brillo key={k} posicion={[Math.cos(a) * rr, Math.sin(a) * rr, 0]} color={k === 0 ? '#FFFFFF' : '#F4F8FF'}
                    radio={0.034 - k * 0.007} luz={k === 0 ? 0.8 : 0} />
                );
              })
            : null}
          {destelloVis ? (
            <group position={[Math.cos(aD) * (R + 0.02), Math.sin(aD) * (R + 0.02), 0]} rotation={[0, 0, frame / 3]}>
              <Pieza forma="caja" medidas={[0.16, 0.012, 0.012]} color="#FFFFFF" brillo="#FFFFFF" contorno={false} />
              <Pieza forma="caja" medidas={[0.012, 0.16, 0.012]} color="#FFFFFF" brillo="#FFFFFF" contorno={false} />
            </group>
          ) : null}
        </group>
      </group>

      {/* chispitas de plata cuando se dice "plata" */}
      {[0, 1, 2, 3, 4].map((i) => {
        const f = frame - tPlata - i * 2;
        if (f < 0 || f > 16) return null;
        const a = 0.6 + i * 0.5;
        const r = R + 0.08 + f * 0.012;
        return (
          <Brillo key={i} posicion={[C[0] + Math.cos(a) * r * 0.8, C[1] + Math.sin(a) * r, C[2] + 0.2]} color={extra} radio={0.018 * (1 - f / 18)} />
        );
      })}

      {/* Etiquetas: solo cuando la voz las nombra */}
      <Etiqueta texto="plata" punto={[0.18, C[1] + 0.22, C[2] + 0.12]} desplazamiento={[0.48, 0.42, 0.05]} escala={plataVis} />
      <Etiqueta texto="canto liso" punto={puntoCanto} desplazamiento={[-0.42, 0.62, 0.1]} escala={lisoVis} color={resalte} />
    </group>
  );
};

