import React from 'react';
import {EscenaProps, Etiqueta, Linea, Brillo, Pieza, caer, aparecer, mover, momento, flotar} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, Mano, Lima, Papel, Polvillo, MonedaIntacta, puntoCanto, TOP} from './Mundo';

// Escala un hijo alrededor de un punto fijo del mundo (sin moverlo de su sitio).
const Pivote: React.FC<{centro: V3; escala: number; dy?: number; children: React.ReactNode}> = ({centro, escala, dy = 0, children}) => {
  if (escala <= 0.001) return null;
  return (
    <group position={[centro[0], centro[1] + dy, centro[2]]} scale={escala}>
      <group position={[-centro[0], -centro[1], -centro[2]]}>{children}</group>
    </group>
  );
};

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, , resalte, mostaza] = paleta.acentos;

  // Golpes sincronizados con la voz
  const tCuidado = momento(palabras, fps, 'cuidado', 0);
  const tSiglos = momento(palabras, fps, 'siglos', 50);
  const tRobaba = momento(palabras, fps, 'robaba', 90);
  const tPlata = momento(palabras, fps, 'plata', 102);
  const tMonedas = momento(palabras, fps, 'monedas', 125);
  const tEsta = momento(palabras, fps, 'esta', 148);
  const fin = Math.max(tEsta + 22, duracion - 10);
  const salida = Math.min(tEsta + 2, fin - 18);

  // Punto del canto donde trabaja la lima
  const c = puntoCanto(0);
  const [cx, cy, cz] = c.pos;
  const tx = Math.sin(c.giro);
  const tz = Math.cos(c.giro);

  // Limado: vaivén vertical rápido, que se detiene al irse la mano
  const vaiven = Math.sin(frame / 2.2) * 0.06 * (1 - aparecer(frame, salida, 8));
  const lateral = Math.sin(frame / 4.4) * 0.025;
  const vete = mover(frame, [salida, salida + 16], [0, 1]);
  const offMano: V3 = [tx * lateral - 0.7 * vete, vaiven + 0.9 * vete, tz * lateral + 0.5 * vete];
  const escMano = 1 - vete;

  // Resaltes (1 a 1,5 s)
  const enRango = (a: number, b: number) => frame >= a && frame < b;
  const resaltar: string[] = [];
  if (enRango(tCuidado, tCuidado + 32)) resaltar.push('lima');
  if (enRango(tMonedas + 15, tMonedas + 55)) resaltar.push('moneda', 'cantoliso');
  const limaRes = resaltar.includes('lima');
  const polvRes = enRango(tPlata, tPlata + 38);

  // Papel y montón de polvillo (crece mientras se lima; se va al final)
  const centroPolv: V3 = [-0.42, TOP, 0.58];
  const crece = mover(frame, [0, tMonedas], [0.35, 1]);
  const quita = 1 - mover(frame, [salida + 4, fin - 2], [0, 1]);
  const escPapel = quita;

  // Cascada de polvillo: del canto al papel
  const activo = frame >= 2 && frame < salida + 6;
  const particulas = activo
    ? Array.from({length: 16}, (_, i) => {
        const periodo = 16;
        const t = ((frame + i * 3.3) % periodo) / periodo;
        const h = Math.sin(i * 12.9898) * 43758.5453;
        const r = h - Math.floor(h);
        const x0 = cx + (r - 0.5) * 0.05;
        const z0 = cz + 0.02;
        const x1 = centroPolv[0] + (r - 0.5) * 0.12;
        const z1 = centroPolv[2] + (r - 0.3) * 0.1;
        const y = cy - 0.03 - (cy - TOP - 0.02) * t * t;
        return (
          <Pieza key={i} forma="esfera" medidas={[0.008 + r * 0.007]} color={polvRes ? resalte : '#EEF2F6'} contorno={false}
            posicion={[x0 + (x1 - x0) * t, y, z0 + (z1 - z0) * t]} />
        );
      })
    : null;

  // Chispas en el punto de contacto
  const chispas = activo
    ? [0, 1, 2].map((i) => {
        const a = frame * 0.9 + i * 2.1;
        const v = (Math.sin(a * 3.1) + 1) / 2;
        return (
          <Brillo key={i} posicion={[cx - 0.04 - v * 0.06, cy + vaiven * 0.5 + Math.sin(a) * 0.05, cz + 0.04 + Math.cos(a) * 0.04]}
            color={i === 1 ? mostaza : '#FFFFFF'} radio={0.009 + v * 0.008} />
        );
      })
    : null;

  // Moneda intacta que cae al lado para comparar
  const cae = caer(frame, fps, Math.min(tSiglos, 50), 1.3);
  const escIntacta = cae.escala * (1 - mover(frame, [salida + 2, fin - 4], [0, 1]));

  // Trayectoria punteada del robo (canto -> papel)
  const ruta = aparecer(frame, tRobaba, 14) * (1 - aparecer(frame, salida, 8));

  // Etiquetas (máx. 2 a la vez) que se van antes del final
  const fuera = 1 - aparecer(frame, salida, 8);
  const etRobo = aparecer(frame, tRobaba, 8) * fuera;
  const etPolv = aparecer(frame, tPlata + 4, 8) * fuera;

  // Destello que anticipa la escena siguiente: recorre el canto
  const destello = aparecer(frame, tMonedas + 15, 6) * (1 - aparecer(frame, fin - 8, 8));
  const ang = (frame - tMonedas) / 7;

  return (
    <group>
      <Mundo paso={0} frame={frame} fps={fps} paleta={paleta} ocultar={['mano', 'lima']} resaltar={resaltar} />

      {/* Mano con lima: lima sin parar y se retira al final */}
      <group position={offMano} scale={escMano > 0.001 ? 1 : 0.0001}>
        <Pivote centro={c.pos} escala={escMano}>
          <Lima paleta={paleta} paso={0} resaltado={limaRes} />
          <Mano paleta={paleta} paso={0} />
        </Pivote>
      </group>
      {chispas}
      {particulas}

      {/* Papel con el polvillo robado */}
      <Pivote centro={centroPolv} escala={escPapel}>
        <Papel paleta={paleta} />
        <Pivote centro={centroPolv} escala={crece}>
          <Polvillo paleta={paleta} frame={frame} resaltado={polvRes} />
        </Pivote>
      </Pivote>

      <Linea desde={[cx - 0.02, cy - 0.04, cz + 0.06]} hasta={[centroPolv[0], TOP + 0.06, centroPolv[2] - 0.02]}
        grosor={0.008} color={rojo} discontinua progreso={ruta} />

      {/* Moneda intacta de comparación */}
      <Pivote centro={[0.3, TOP, 0.7]} escala={escIntacta} dy={cae.y}>
        <group position={[0.3, TOP, 0.7]} rotation={[0, 0, cae.giro]}>
          <group position={[-0.3, -TOP, -0.7]}>
            <MonedaIntacta paleta={paleta} />
          </group>
        </group>
      </Pivote>

      {/* Destello recorriendo el borde de la moneda */}
      {destello > 0.01 ? (
        <Brillo posicion={[Math.cos(ang) * 0.43 * Math.cos(0.35), TOP + 0.42 + Math.sin(ang) * 0.43, 0.15 - Math.cos(ang) * 0.43 * Math.sin(0.35) + 0.06]}
          color="#FFFFFF" radio={0.03 * destello + flotar(frame, 0.004, 10)} />
      ) : null}

      <Etiqueta texto="robando plata" punto={[0.05, TOP + 0.84, 0.17]} desplazamiento={[0.32, 0.42, 0]} escala={etRobo} color={rojo} />
      <Etiqueta texto="polvillo" punto={[centroPolv[0], TOP + 0.04, centroPolv[2]]} desplazamiento={[-0.25, 0.35, 0.2]} escala={etPolv} />
    </group>
  );
};

escenas.Escena2:
import React from 'react';
import {interpolate} from 'remotion';
import {EscenaProps, Pieza, Etiqueta, Brillo, caer, aparecer, mover, momento, flotar} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, Moneda, CantoLiso, Mano, Lima, Papel, Polvillo, puntoCanto, poseMoneda, TOP, R, G} from './Mundo';

const PASO = 2;

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, extra] = paleta.acentos;

  // Golpes con la voz
  const tAlguien = momento(palabras, fps, 'alguien', 1);
  const tRaspa = momento(palabras, fps, 'raspa', 26);
  const tBorde = momento(palabras, fps, 'borde', 66);
  const tCasi = momento(palabras, fps, 'casi', 90);
  const tNota = momento(palabras, fps, 'nota', 105);
  const tFin = duracion - 6;

  // Al final el mundo queda exactamente como el paso 3
  if (frame >= tFin) {
    return (
      <group>
        <Mundo paso={PASO + 1} frame={frame} fps={fps} paleta={paleta} />
      </group>
    );
  }

  // Moneda que se va adelgazando (escala desde el punto de apoyo)
  const s = interpolate(frame, [tRaspa, tCasi], [1, 0.95], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const apoyo: V3 = [0, TOP, poseMoneda(PASO).z];

  // Mano con lima: entra, raspa arriba y abajo por el canto, sale
  const entra = aparecer(frame, tAlguien, 14);
  const sale = aparecer(frame, tCasi, 16);
  const fuera = (1 - entra) + sale;
  const c = puntoCanto(PASO);
  const outX = -Math.cos(c.giro);
  const outZ = Math.sin(c.giro);
  const raspando = aparecer(frame, tRaspa, 4) * (1 - aparecer(frame, tCasi - 4, 6));
  const dy = Math.sin((frame - tRaspa) / 2.2) * 0.075 * raspando;
  const manoPos: V3 = [outX * 0.9 * fuera, dy + 0.6 * fuera, outZ * 0.9 * fuera];
  const verMano = fuera < 1.4;

  // Resaltes
  const limaRes = frame >= tRaspa && frame < tRaspa + 32;
  const cantoRes = frame >= tBorde && frame < tBorde + 40;

  // Papel que cae al inicio (primer golpe)
  const papel = caer(frame, fps, tAlguien + 4, 0.9);

  // Polvillo que crece sobre el papel
  const polvo = interpolate(frame, [tRaspa + 8, tCasi + 8], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const pPapel: V3 = [-0.42, TOP + 0.004, 0.58];

  // Partículas que caen del canto al papel
  const activo = frame >= tRaspa && frame < tCasi + 12;
  const desde: V3 = [c.pos[0] * s - 0.01, c.pos[1] - 0.04 + dy, apoyo[2] + (c.pos[2] - apoyo[2]) * s + 0.01];
  const particulas = activo
    ? Array.from({length: 12}, (_, i) => {
        const per = 20;
        const loc = ((frame - tRaspa + i * 7.3) % per) / per;
        const h = Math.sin(i * 12.9898) * 43758.5453;
        const r = h - Math.floor(h);
        const hasta: V3 = [pPapel[0] + (r - 0.5) * 0.12, pPapel[1] + 0.01, pPapel[2] + (r - 0.5) * 0.1];
        const x = desde[0] + (hasta[0] - desde[0]) * loc + (r - 0.5) * 0.04;
        const z = desde[2] + (hasta[2] - desde[2]) * loc;
        const y = desde[1] + (hasta[1] - desde[1]) * loc * loc + Math.sin(loc * Math.PI) * 0.04;
        return (
          <Pieza key={i} forma="esfera" medidas={[0.008 + r * 0.006]} color={i % 3 ? '#EEF2F6' : '#C9CFD7'} contorno={false} posicion={[x, y, z]} />
        );
      })
    : null;

  // Chispitas en el punto de contacto mientras raspa
  const chispas = raspando > 0.3
    ? [0, 1, 2].map((i) => {
        const a = frame * 0.9 + i * 2.1;
        return (
          <Brillo key={i} color="#FFFFFF" radio={0.01 + 0.006 * Math.abs(Math.sin(a))}
            posicion={[desde[0] + outX * 0.05 + Math.cos(a) * 0.03, desde[1] + 0.04 + Math.sin(a * 1.3) * 0.04, desde[2] + outZ * 0.05]} />
        );
      })
    : null;

  // Anillo fantasma: el tamaño original, para ver que casi no se nota
  const pose = poseMoneda(PASO);
  const fantasma = aparecer(frame, tNota, 8) * (1 - aparecer(frame, tFin - 10, 8));
  const giroAnillo = flotar(frame, 0.02, 60);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['moneda', 'cantoliso']} />

      {/* Moneda protagonista, adelgazando mientras la raspan */}
      <group position={apoyo} scale={s}>
        <group position={[-apoyo[0], -apoyo[1], -apoyo[2]]}>
          <Moneda paleta={paleta} frame={frame} paso={PASO} />
          <CantoLiso paleta={paleta} frame={frame} paso={PASO} resaltado={cantoRes} />
        </group>
      </group>

      {/* Mano y lima en el canto */}
      {verMano ? (
        <group position={manoPos} rotation={[0, 0, mover(frame, [tCasi, tCasi + 14], [0, -0.25])]}>
          <Lima paleta={paleta} frame={frame} paso={PASO} resaltado={limaRes} />
          <Mano paleta={paleta} frame={frame} paso={PASO} />
        </group>
      ) : null}
      {chispas}

      {/* Papel doblado y polvillo plateado */}
      <group position={[0, papel.y, 0]} rotation={[0, 0, papel.giro * 0.3]} scale={papel.escala}>
        <Papel paleta={paleta} frame={frame} paso={PASO + 1} />
      </group>
      {polvo > 0.01 ? (
        <group position={pPapel} scale={[polvo, Math.max(0.01, polvo), polvo]}>
          <group position={[-pPapel[0], -pPapel[1], -pPapel[2]]}>
            <Polvillo paleta={paleta} frame={frame} paso={PASO + 1} />
          </group>
        </group>
      ) : null}
      {particulas}

      {/* Contorno punteado del tamaño original */}
      {fantasma > 0.01 ? (
        <group position={[pose.x, TOP + R, pose.z]} rotation={[0, pose.giro, 0]}>
          <group position={[0, 0, G / 2 + 0.012]} rotation={[0, 0, giroAnillo]}>
            {Array.from({length: 26}, (_, i) => (
              <Pieza key={i} forma="toro" medidas={[R, 0.006, (Math.PI * 2) / 52]} color={extra} contorno={false}
                rotacion={[0, 0, (i / 26) * Math.PI * 2]} opacidad={fantasma} />
            ))}
          </group>
        </group>
      ) : null}

      {/* Etiqueta del borde, a un lado */}
      <Etiqueta texto="borde" punto={[desde[0], desde[1] - 0.12, desde[2]]} desplazamiento={[-0.5, -0.12, 0.15]}
        color={resalte} escala={aparecer(frame, tBorde, 8) * (1 - aparecer(frame, tCasi + 6, 8))} />
    </group>
  );
};

escenas.Escena4:
// Escena 5: «Se llamaba recortar monedas, y era un problema enorme en Inglaterra.»
// Sello RECORTE que cae y golpea; fila raspada frente a una moneda intacta; aros que marcan la plata perdida.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Flecha, Linea, Etiqueta, Aro, Brillo, Pieza, caer, momento, flotar} from '../lib3d';
import {Mundo, Sello, MonedaIntacta, TOP} from './Mundo';

const PASO = 4;
const SELLO: [number, number, number] = [0.68, TOP, 0.28];
const FILA_X = [-0.8, -0.55, -0.3, -0.05];

const rango = (frame: number, ent: number[], sal: number[]) =>
  interpolate(frame, ent, sal, {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic)});

export const Escena4: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, resalte, mostaza] = paleta.acentos;
  const fin = Math.max(150, duracion - 4);

  const tRecortar = momento(palabras, fps, 'recortar', 21);
  const tMonedas = momento(palabras, fps, 'monedas', 49);
  const tProblema = momento(palabras, fps, 'problema', 93);
  const tEnorme = momento(palabras, fps, 'enorme', 105);
  const tInglaterra = momento(palabras, fps, 'inglaterra', 140);

  // Golpe inicial: la plata de la fila viajó al lingote (camino punteado + flecha).
  const camino = rango(frame, [2, 16, 38, 48], [0, 1, 1, 0]);

  // El sello cae en "recortar", vuelve a golpear en "problema" y sale volando en "Inglaterra".
  const caida = caer(frame, fps, tRecortar, 1.4);
  const golpe = (t: number) => {
    const f = frame - t;
    if (f < 0 || f > 14) return 0;
    return Math.sin((f / 14) * Math.PI);
  };
  const g2 = golpe(tProblema);
  const alzar = rango(frame, [tProblema - 8, tProblema], [0, 0.18]) * (frame < tProblema ? 1 : 0);
  const salida = rango(frame, [tInglaterra + 6, fin - 6], [0, 1]);
  const escalaSello = 1.4 * caida.escala * (1 - salida);
  const ySello = caida.y + alzar + salida * 0.9 + flotar(frame, 0.006, 50) * (frame > tRecortar + 20 ? 1 : 0);
  const aplasta: [number, number, number] = [1 + g2 * 0.12, 1 - g2 * 0.22, 1 + g2 * 0.12];

  // Chispas de tinta al golpear.
  const chispas = (t: number) => {
    const f = frame - t;
    if (f < 0 || f > 16) return null;
    const k = f / 16;
    return Array.from({length: 6}, (_, i) => {
      const a = (i / 6) * Math.PI * 2;
      return (
        <Pieza key={`${t}-${i}`} forma="esfera" medidas={[0.018 * (1 - k)]} color={rojo} contorno={false}
          posicion={[SELLO[0] + Math.cos(a) * (0.2 + k * 0.25), TOP + 0.02 + Math.sin(k * Math.PI) * 0.12, SELLO[2] + Math.sin(a) * (0.15 + k * 0.2)]} />
      );
    });
  };

  // La moneda intacta llega tras "monedas" y se queda (estado del paso 5).
  const tIntacta = tMonedas + 14;
  const intacta = caer(frame, fps, tIntacta, 1.2);

  // Resaltes: la fila al decir "monedas"; la intacta al llegar.
  const resaltar: string[] = [];
  if (frame >= tMonedas && frame < tMonedas + 38) resaltar.push('fila');
  const intactaResaltada = frame >= tIntacta + 2 && frame < tIntacta + 40;

  // Aros fantasma: el tamaño que tenían antes de raspar.
  const aros = rango(frame, [tEnorme, tEnorme + 14, fin - 18, fin - 4], [0, 1, 1, 0]);
  const pulso = 1 + Math.sin(frame / 5) * 0.03 * aros;

  // Etiquetas (máximo dos textos con el cartel del sello).
  const etIntacta = rango(frame, [tIntacta + 12, tIntacta + 20, tEnorme + 10, tEnorme + 16], [0, 1, 1, 0]);
  const etRaspadas = rango(frame, [tEnorme + 18, tEnorme + 26, fin - 14, fin - 6], [0, 1, 1, 0]);

  // Brillo que recorre la fila (movimiento constante).
  const brilloX = interpolate((frame % 60) / 60, [0, 1], [-0.85, 0]);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['monedaintacta']} resaltar={resaltar} />

      {/* Camino de la plata: de la fila al lingote */}
      {camino > 0.001 ? (
        <group>
          <Linea desde={[-0.4, TOP + 0.08, 0.7]} hasta={[0.1, TOP + 0.35, 0.0]} grosor={0.01} color={mostaza} discontinua progreso={camino} />
          <Flecha desde={[0.1, TOP + 0.35, 0.0]} hasta={[0.45, TOP + 0.16, -0.45]} color={mostaza} grosor={0.02} progreso={rango(frame, [12, 24], [0, 1]) * (camino > 0.05 ? 1 : 0)} />
        </group>
      ) : null}

      {/* Sello RECORTE, grande */}
      {escalaSello > 0.001 ? (
        <group position={[SELLO[0], SELLO[1] + ySello, SELLO[2]]} rotation={[0, salida * 1.5, caida.giro + salida * 0.4]} scale={escalaSello}>
          <group scale={aplasta}>
            <group position={[-SELLO[0], -SELLO[1], -SELLO[2]]}>
              <Sello paleta={paleta} frame={frame} paso={PASO} />
            </group>
          </group>
        </group>
      ) : null}
      {chispas(tRecortar)}
      {chispas(tProblema)}

      {/* Moneda intacta para comparar */}
      <group position={[0.3, intacta.y, 0.7]} scale={intacta.escala}>
        <group position={[-0.3, 0, -0.7]}>
          <MonedaIntacta paleta={paleta} resaltado={intactaResaltada} frame={frame} paso={PASO} />
        </group>
      </group>

      {/* Aros: tamaño original alrededor de cada moneda raspada */}
      {aros > 0.001
        ? FILA_X.map((x, i) => (
            <group key={x} scale={[pulso, 1, pulso]} position={[x, 0, 0.72 - i * 0.02]}>
              <Aro posicion={[0, TOP + 0.03, 0]} radio={0.125} color={resalte} grosor={0.008} progreso={aros} />
            </group>
          ))
        : null}
      {aros > 0.001 ? <Aro posicion={[0.3, TOP + 0.03, 0.7]} radio={0.132} color={crema} grosor={0.008} progreso={aros} /> : null}

      <Etiqueta texto="intacta" punto={[0.3, TOP + 0.03, 0.7]} desplazamiento={[-0.1, 0.32, 0.3]} escala={etIntacta} />
      <Etiqueta texto="raspadas" punto={[-0.55, TOP + 0.03, 0.7]} desplazamiento={[-0.15, 0.4, 0.25]} escala={etRaspadas} />

      {/* Destello que recorre la fila */}
      <Brillo posicion={[brilloX, TOP + 0.035, 0.73]} color="#FFFFFF" radio={0.01} />
    </group>
  );
};

escenas.Escena5:
import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Flecha, Aro, Brillo, Linea, caer, aparecer, desaparecer, mover, momento, flotar} from '../lib3d';
import {Mundo, Balanza, poseMoneda, R, TOP} from './Mundo';

export const Escena5: React.FC<EscenaProps> = ({frame, fps, palabras, paleta}) => {
  const [rojo, , resalte, mostaza] = paleta.acentos;

  // Golpes sincronizados con la voz
  const tCada = momento(palabras, fps, 'cada', 1);
  const tMoneda = momento(palabras, fps, 'moneda', 11);
  const tPesaba = momento(palabras, fps, 'pesaba', 24);
  const tPoquito = momento(palabras, fps, 'poquito', 44);
  const tMenos = momento(palabras, fps, 'menos', 54);
  const tCasi = momento(palabras, fps, 'casi', 82);
  const tNotaba = momento(palabras, fps, 'notaba', 108);
  const tSimple = momento(palabras, fps, 'simple', 122);
  const fin = 151;

  // Balanza: cae al empezar y se inclina al decir «pesaba» (termina en 0.2, igual que paso 6)
  const cae = caer(frame, fps, tCada + 5, 1.0);
  const f = frame - tPesaba;
  const incl = f <= 0 ? 0 : 0.2 * (1 - Math.exp(-f / 6) * Math.cos(f / 3.2));
  const bx = -0.82;
  const bz = -0.2;
  const golpe = aparecer(frame, tCada + 5, 10) * desaparecer(frame, tCada + 18, 10);

  // Platillos (para flechas y etiqueta)
  const exI = bx - 0.29 * Math.cos(incl);
  const eyI = TOP + 0.62 - 0.29 * Math.sin(incl) - 0.25;
  const exR = bx + 0.29 * Math.cos(incl);
  const eyR = TOP + 0.62 + 0.29 * Math.sin(incl) - 0.25;
  const pesoArriba = mover(frame, [tPesaba, tPesaba + 12], [0, 1]);

  // Resaltes en el momento de la palabra
  const resaltar: string[] = [];
  if (frame >= tMoneda && frame < tMoneda + 36) resaltar.push('monedaintacta');
  if (frame >= tPoquito && frame < tPoquito + 38) resaltar.push('fila');
  if (frame >= tNotaba && frame < tNotaba + 40) resaltar.push('cantoliso');
  const balanzaResaltada = frame >= tPesaba && frame < tPesaba + 36;

  // Lupa que recorre el canto liso y no encuentra nada
  const pm = poseMoneda(5);
  const u: [number, number, number] = [-Math.cos(pm.giro), 0, Math.sin(pm.giro)];
  const lupaEsc = aparecer(frame, tCasi, 10) * desaparecer(frame, fin - 10, 9);
  const theta = mover(frame, [tCasi, tSimple + 8], [-0.7, 0.75]) + flotar(frame, 0.05, 30);
  const rc = R * pm.k;
  const enCanto = (r: number, th: number): [number, number, number] => [
    pm.x + r * Math.cos(th) * u[0],
    pm.y + r * Math.sin(th),
    pm.z + r * Math.cos(th) * u[2],
  ];
  const lupaPos = enCanto(rc + 0.2, theta);
  const lupaMira = enCanto(rc, theta);
  const brilloLente = 0.5 + 0.5 * Math.sin(frame / 4);

  return (
    <group>
      <Mundo paso={5} frame={frame} fps={fps} paleta={paleta} resaltar={resaltar} />

      {/* Balanza de platillos: llega y compara */}
      <group position={[bx, TOP + cae.y, bz]} scale={cae.escala} rotation={[0, 0, cae.giro * 0.3]}>
        <group position={[-bx, -TOP, -bz]}>
          <Balanza paleta={paleta} frame={frame} paso={6} inclinacion={incl} resaltado={balanzaResaltada} />
        </group>
      </group>
      <Aro posicion={[bx, TOP, bz]} radio={0.15 + 0.25 * (1 - golpe)} color={mostaza} progreso={golpe} grosor={0.015} />

      {/* Fuerzas: la intacta pesa más (flecha larga), la raspada menos (flecha corta) */}
      <Flecha desde={[exI, eyI - 0.03, bz + 0.16]} hasta={[exI, eyI - 0.3, bz + 0.16]} color={rojo} grosor={0.022} progreso={pesoArriba} />
      <Flecha desde={[exR, eyR - 0.03, bz + 0.16]} hasta={[exR, eyR - 0.14, bz + 0.16]} color={rojo} grosor={0.016} progreso={mover(frame, [tMenos - 4, tMenos + 8], [0, 1])} />
      <Etiqueta texto="pesa menos" punto={[exR, eyR + 0.05, bz]} desplazamiento={[0.05, 0.7, 0.3]} escala={aparecer(frame, tMenos, 8)} color={resalte} />

      {/* Lupa: mira el canto liso */}
      {lupaEsc > 0.001 ? (
        <group position={lupaPos} scale={lupaEsc}>
          <Pieza forma="toro" medidas={[0.11, 0.014]} color={mostaza} />
          <Pieza forma="cilindro" medidas={[0.105, 0.105, 0.006]} color="#CFE6F2" opacidad={0.35} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
          <Pieza forma="cilindro" medidas={[0.018, 0.016, 0.04]} color={mostaza} posicion={[0.09, -0.09, 0]} rotacion={[0, 0, Math.PI / 4]} />
          <Pieza forma="cilindro" medidas={[0.02, 0.026, 0.2]} color="#2A2320" posicion={[0.17, -0.17, 0]} rotacion={[0, 0, Math.PI / 4]} />
          <Pieza forma="esfera" medidas={[0.026]} color="#2A2320" posicion={[0.245, -0.245, 0]} />
          <Brillo posicion={[-0.04, 0.04, 0.01]} color="#FFFFFF" radio={0.012 + 0.006 * brilloLente} />
        </group>
      ) : null}
      {lupaEsc > 0.001 ? (
        <Linea desde={lupaPos} hasta={lupaMira} grosor={0.006} color={mostaza} discontinua progreso={lupaEsc} />
      ) : null}
      <Etiqueta texto="sin marcas" punto={enCanto(rc, 0.2)} desplazamiento={[-0.6, 0.32, 0.2]} escala={aparecer(frame, tSimple, 8)} />
    </group>
  );
};

escenas.Escena3:
import React from 'react';
import {interpolate} from 'remotion';
import {EscenaProps, Pieza, Etiqueta, Brillo, caer, aparecer, rebote, flotar, momento} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, Papel, Polvillo, Fila, Lingote, TOP} from './Mundo';

const PLATA = '#C9CFD7';
const PLATA_CLARA = '#EEF2F6';
const PIEL = '#E9B793';
const LATON = '#C99A3A';
const C: V3 = [0.55, TOP, -0.5]; // crisol, en el sitio exacto del lingote
const BOCA: V3 = [0.55, TOP + 0.2, -0.5];
const XS = [-0.8, -0.55, -0.3, -0.05];
const posFila = (i: number): V3 => [XS[i], TOP, 0.72 - i * 0.02];
const cl = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;

const arco = (a: V3, b: V3, u: number, h: number): V3 => {
  const t = Math.min(1, Math.max(0, u));
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t + h * Math.sin(Math.PI * t), a[2] + (b[2] - a[2]) * t];
};

/** Mota de plata que vuela de una moneda al crisol. */
const Mota: React.FC<{desde: V3; t: number; frame: number; dur?: number; tam?: number}> = ({desde, t, frame, dur = 16, tam = 0.016}) => {
  const u = (frame - t) / dur;
  if (u < 0 || u > 1) return null;
  return <Pieza forma="esfera" medidas={[tam]} color={PLATA_CLARA} contorno={false} posicion={arco(desde, BOCA, u, 0.5)} />;
};

/** Réplica exacta de las monedas chicas de la fila (para animarlas una a una). */
const MonedaFila: React.FC<{i: number; frame: number; fps: number; tCae: number; color: string}> = ({i, frame, fps, tCae, color}) => {
  const c = caer(frame, fps, tCae, 1.1);
  if (c.escala <= 0.001) return null;
  const [x, y, z] = posFila(i);
  const r = 0.105;
  return (
    <group position={[x, y + c.y, z]} rotation={[c.giro * 0.6, 0, c.giro * 0.4]} scale={c.escala}>
      <Pieza forma="cilindro" medidas={[r, r, 0.026, 36]} color={color} posicion={[0, 0.013, 0]} />
      <Pieza forma="toro" medidas={[r * 0.86, 0.007]} color={PLATA_CLARA} posicion={[0, 0.026, 0]} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
      <Pieza forma="cilindro" medidas={[r * 0.45, r * 0.45, 0.006]} color={PLATA_CLARA} posicion={[0, 0.028, 0]} contorno={false} />
    </group>
  );
};

/** Lima pequeña con la mano que la sostiene (en horizontal, para raspar monedas acostadas). */
const LimaConMano: React.FC<{color: string}> = ({color}) => (
  <group>
    <Pieza forma="caja" medidas={[0.32, 0.014, 0.045]} color={color} />
    <Pieza forma="caja" medidas={[0.28, 0.016, 0.02]} color="#9AA0A8" contorno={false} posicion={[0, 0.002, 0]} />
    <Pieza forma="cilindro" medidas={[0.028, 0.028, 0.03]} color={LATON} posicion={[0.175, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
    <Pieza forma="cilindro" medidas={[0.026, 0.032, 0.2]} color="#8B5A2B" posicion={[0.29, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
    <group position={[0.3, 0.05, 0]}>
      <Pieza forma="esfera" medidas={[0.075]} color={PIEL} escala={[1.2, 0.9, 1.1]} />
      {[0, 1, 2, 3].map((k) => (
        <Pieza key={k} forma="capsula" medidas={[0.02, 0.04]} color={PIEL} posicion={[-0.05 + k * 0.034, -0.045, 0.06]} rotacion={[Math.PI / 2, 0, 0]} />
      ))}
      <Pieza forma="capsula" medidas={[0.02, 0.05]} color={PIEL} posicion={[-0.07, -0.02, -0.05]} rotacion={[0.4, 0, 1.2]} />
      <group rotation={[0, 0, -0.9]}>
        <Pieza forma="toro" medidas={[0.072, 0.02]} color="#F3EEE4" posicion={[0, 0.08, 0]} rotacion={[Math.PI / 2, 0, 0]} />
        <Pieza forma="cilindro" medidas={[0.075, 0.085, 0.42]} color="#6A4B8C" posicion={[0, 0.3, 0]} />
      </group>
    </group>
  </group>
);

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, mostaza] = paleta.acentos;

  const tCien = momento(palabras, fps, 'cien', 33);
  const tMon = momento(palabras, fps, 'monedas', 44);
  const tJunta = momento(palabras, fps, 'junta', 72);
  const tPeq = momento(palabras, fps, 'pequeño', 90);
  const tLing = momento(palabras, fps, 'lingote', 105);
  const finResalte = Math.min(tLing + 36, duracion - 6);

  // Inicio: el polvillo del papel vuela al crisol y el papel se retira.
  const sPolvo = 1 - aparecer(frame, 2, 12);
  const sPapel = 1 - aparecer(frame, 12, 10);

  // Raspado moneda por moneda.
  const tRaspa = [0, 1, 2, 3].map((i) => tMon + i * 11);
  const filaReal = frame >= tMon + 46;
  const fr = [tMon - 8, tMon, tMon + 8, tMon + 11, tMon + 19, tMon + 22, tMon + 30, tMon + 33, tMon + 41];
  const lx = interpolate(frame, fr, [XS[0] - 0.4, XS[0], XS[0], XS[1], XS[1], XS[2], XS[2], XS[3], XS[3]], cl);
  const lz = interpolate(frame, fr, [0.84, 0.84, 0.84, 0.82, 0.82, 0.8, 0.8, 0.78, 0.78], cl);
  const salto = [0, 1, 2].reduce((acc, i) => {
    const a = tRaspa[i] + 8;
    const u = (frame - a) / 3;
    return u > 0 && u < 1 ? acc + Math.sin(u * Math.PI) * 0.08 : acc;
  }, 0);
  const raspando = frame >= tMon && frame < tMon + 41 && salto === 0;
  const vaiven = raspando ? Math.sin(frame * 1.5) * 0.045 : 0;
  const sLima = aparecer(frame, tMon - 10, 6) * (1 - aparecer(frame, tMon + 42, 8));
  const iActiva = Math.min(3, Math.max(0, Math.floor((frame - tMon) / 11)));

  // Crisol: se llena con cada moneda, late en "pequeño" y se vuelve lingote.
  const lleno = 0.3 * aparecer(frame, 14, 10) + tRaspa.reduce((s, t) => s + 0.175 * aparecer(frame, t + 16, 8), 0);
  const dp = frame - tPeq;
  const latido = dp > 0 ? 0.08 * Math.sin(dp / 2) * Math.exp(-dp / 8) : 0;
  const sCrisol = 1 - aparecer(frame, tLing - 3, 7);
  const sLingote = frame < tLing - 2 ? 0 : frame > tLing + 32 ? 1 : rebote(frame, fps, tLing - 2);
  const ds = frame - tLing;

  // Trayectoria punteada de la fila al crisol.
  const sCamino = 1 - aparecer(frame, tLing - 6, 8);

  return (
    <group>
      <Mundo paso={3} frame={frame} fps={fps} paleta={paleta} ocultar={['papel', 'polvillo']} />

      {/* papel y polvillo de la escena anterior, que se van */}
      {sPapel > 0.001 ? (
        <group position={[-0.42, TOP, 0.58]} scale={sPapel}>
          <group position={[0.42, -TOP, -0.58]}><Papel paleta={paleta} /></group>
        </group>
      ) : null}
      {sPolvo > 0.001 ? (
        <group position={[-0.42, TOP, 0.58]} scale={sPolvo}>
          <group position={[0.42, -TOP, -0.58]}><Polvillo paleta={paleta} frame={frame} /></group>
        </group>
      ) : null}
      {[0, 1, 2, 3, 4, 5].map((k) => (
        <Mota key={`p${k}`} desde={[-0.42, TOP + 0.03, 0.58]} t={1 + k * 2} frame={frame} dur={15} tam={0.02} />
      ))}

      {/* la fila de monedas: caen una a una y se resaltan al rasparlas */}
      {filaReal ? (
        <Fila paleta={paleta} frame={frame} paso={4} />
      ) : (
        [0, 1, 2, 3].map((i) => (
          <MonedaFila key={i} i={i} frame={frame} fps={fps} tCae={tCien + i * 4}
            color={frame >= tRaspa[i] && frame < tRaspa[i] + 11 ? resalte : PLATA} />
        ))
      )}

      {/* lima con la mano raspando el borde */}
      {sLima > 0.001 ? (
        <group position={[lx + 0.06 + vaiven, TOP + 0.035 + salto, lz]} rotation={[0, -0.35, 0.18]} scale={sLima}>
          <LimaConMano color="#6F757D" />
        </group>
      ) : null}
      {raspando
        ? [0, 1].map((k) => {
            const [x, , z] = posFila(iActiva);
            return <Brillo key={`c${k}`} posicion={[x + 0.02 + Math.sin(frame * 2 + k) * 0.04, TOP + 0.04 + ((frame + k * 3) % 5) * 0.012, z + 0.1]} color="#FFFFFF" radio={0.011} />;
          })
        : null}
      {tRaspa.map((t, i) =>
        [0, 1, 2, 3].map((k) => {
          const [x, , z] = posFila(i);
          return <Mota key={`m${i}-${k}`} desde={[x + 0.02, TOP + 0.04, z + 0.09]} t={t + 2 + k * 2} frame={frame} dur={17} />;
        }),
      )}

      {/* camino punteado del polvillo */}
      {sCamino > 0.001
        ? Array.from({length: 14}, (_, k) =>
            frame >= tJunta + k ? (
              <Pieza key={`d${k}`} forma="esfera" medidas={[0.013]} color={mostaza} contorno={false}
                posicion={arco([-0.42, TOP + 0.06, 0.72], BOCA, (k + 0.5) / 14, 0.5)} escala={sCamino} />
            ) : null,
          )
        : null}

      {/* crisol con plata fundida */}
      {sCrisol > 0.001 ? (
        <group position={C} scale={[sCrisol * (1 + latido), sCrisol * (1 - latido), sCrisol * (1 + latido)]}>
          <Pieza forma="cilindro" medidas={[0.14, 0.1, 0.19]} color="#8A6A52" posicion={[0, 0.095, 0]} />
          <Pieza forma="toro" medidas={[0.135, 0.018]} color="#7A5A44" posicion={[0, 0.19, 0]} rotacion={[Math.PI / 2, 0, 0]} />
          <Pieza forma="cilindro" medidas={[0.122, 0.122, 0.006]} color="#3A2A1E" contorno={false} posicion={[0, 0.192, 0]} />
          <Pieza forma="cilindro" medidas={[0.115, 0.115, 0.008]} color={PLATA_CLARA} contorno={false}
            posicion={[0, 0.197, 0]} escala={[0.2 + lleno * 0.8, 1, 0.2 + lleno * 0.8]}
            brillo="#FFB347" opacidad={1} />
          <Brillo posicion={[0, 0.22 + flotar(frame, 0.01, 20), 0]} color="#FFD08A" radio={0.012 + lleno * 0.02} luz={0.3 + lleno * 0.6} />
          <Pieza forma="caja" medidas={[0.3, 0.03, 0.2]} color="#6B5A4A" posicion={[0, -0.0, 0]} escala={[1, 0.3, 1]} />
          {/* tenazas apoyadas */}
          {[-0.02, 0.02].map((dz) => (
            <Pieza key={dz} forma="caja" medidas={[0.38, 0.014, 0.014]} color="#3F4A4C" posicion={[-0.25, 0.03, 0.12 + dz]} rotacion={[0, 0.3 + dz * 4, 0.08]} />
          ))}
        </group>
      ) : null}

      {/* destello y el lingote nuevo */}
      {ds >= 0 && ds < 14
        ? Array.from({length: 8}, (_, k) => {
            const a = (k / 8) * Math.PI * 2;
            const d = 0.05 + ds * 0.022;
            return <Brillo key={`b${k}`} posicion={[C[0] + Math.cos(a) * d, BOCA[1] - 0.05 + Math.sin(a) * d * 0.7, C[2] + 0.05]} color={k % 2 ? '#FFFFFF' : mostaza} radio={0.018 * (1 - ds / 14)} />;
          })
        : null}
      {sLingote > 0.001 ? (
        <group position={C} scale={sLingote}>
          <group position={[-C[0], -C[1], -C[2]]}>
            <Lingote paleta={paleta} frame={frame} paso={4} resaltado={frame >= tLing && frame < finResalte} />
          </group>
        </group>
      ) : null}

      {/* etiquetas */}
      <Etiqueta texto="100 monedas" punto={[-0.55, TOP + 0.03, 0.74]} desplazamiento={[-0.05, 0.3, 0.06]}
        escala={aparecer(frame, tCien + 3, 8) * (1 - aparecer(frame, tLing - 10, 8))} />
      <Etiqueta texto="un lingote" punto={[0.55, TOP + 0.1, -0.5]} desplazamiento={[0.1, 0.6, 0.35]}
        escala={aparecer(frame, tLing + 3, 8) * (1 - aparecer(frame, duracion - 12, 8))} />
    </group>
  );
};

escenas.Escena6:
// Escena 7: «La solución fue marcar el borde con ranuras.»
// Se van la balanza y las monedas chicas, entra la máquina de rodillos, recorre el canto
// y le graba rayitas verticales parejas. Termina igual que <Mundo paso={7} />.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Etiqueta, Flecha, Linea, Brillo, aparecer, momento} from '../lib3d';
import {Mundo, Moneda, CantoLiso, CantoEstriado, Balanza, Fila, MonedaIntacta, Rodillos, TOP, R, G, puntoCanto} from './Mundo';

const PASO = 6;
const CL = {extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const};

// Escala un grupo tomando como apoyo un punto (el objeto no se despega de la mesa).
const Pivote: React.FC<{en: [number, number, number]; s: number; dy?: number; children: React.ReactNode}> = ({en, s, dy = 0, children}) => {
  if (s <= 0.001) return null;
  return (
    <group position={[en[0], en[1] + dy, en[2]]} scale={s}>
      <group position={[-en[0], -en[1], -en[2]]}>{children}</group>
    </group>
  );
};

export const Escena6: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, extra] = paleta.acentos;
  const fin = Math.max(duracion, 100);

  // Golpes con la voz
  const tSolucion = momento(palabras, fps, 'solución', 19);
  const tMarcar = momento(palabras, fps, 'marcar', 45);
  const tBorde = momento(palabras, fps, 'borde', 67);
  const tRanuras = momento(palabras, fps, 'ranuras', 86);

  // 1) Lo del paso anterior sale de escena con un salto de dibujo animado (frame 2 en adelante)
  const salida = (t: number) => interpolate(frame, [t, t + 12], [1, 0], {...CL, easing: Easing.in(Easing.back(2.2))});
  const sBalanza = salida(2);
  const sFila = salida(5);
  const sIntacta = salida(8);

  // 2) La moneda se recuña: vuelve a su tamaño completo antes de que la toquen los rodillos
  const k = interpolate(frame, [tSolucion, tMarcar - 4], [0.95, 1], {...CL, easing: Easing.inOut(Easing.cubic)});
  const fR = frame - tRanuras;
  const saltito = fR > 0 ? Math.exp(-fR / 6) * Math.abs(Math.sin(fR / 2.2)) * 0.035 : 0;

  // 3) La máquina de rodillos entra, graba y se va
  const c = puntoCanto(7);
  const g = c.giro;
  const afuera: [number, number, number] = [-Math.cos(g), 0, Math.sin(g)];
  const arriba = 0;
  const entra = interpolate(frame, [3, tMarcar - 2], [1.0, 0], {...CL, easing: Easing.out(Easing.cubic)});
  const sale = interpolate(frame, [tRanuras + 8, tRanuras + 24], [0, 1.0], {...CL, easing: Easing.in(Easing.cubic)});
  const dist = entra + sale;
  const sRod = interpolate(frame, [tRanuras + 14, tRanuras + 26], [1, 0], CL) * interpolate(frame, [2, 8], [0, 1], CL);
  const grabado = interpolate(frame, [tMarcar, tRanuras], [0, 1], {...CL, easing: Easing.inOut(Easing.quad)});
  const grabando = frame >= tMarcar && frame < tRanuras;
  const giroRodillo = interpolate(frame, [tMarcar, tRanuras], [0, 90], CL);
  const vibra = grabando ? Math.sin(frame * 2.1) * 0.006 : 0;
  const rodResaltado = frame >= tSolucion && frame < tSolucion + 38;

  // 4) Ranuras: aparecen desde el punto de contacto hacia los dos lados
  const listo = frame >= tRanuras;
  const ranurasResaltadas = frame >= tRanuras && frame < tRanuras + 30;
  const N = 72;
  const rr = R + 0.004;
  const ranuras = Array.from({length: N}, (_, i) => {
    const a = (i / N) * Math.PI * 2;
    const d = Math.abs(a - Math.PI);
    if (d > grabado * Math.PI + 0.001 || grabado <= 0) return null;
    const nueva = d > grabado * Math.PI - 0.25;
    return (
      <Pieza key={i} forma="caja" medidas={[(Math.PI * 2 * rr) / N / 2, G * 0.9, 0.012]} color={nueva ? extra : '#EEF2F6'} contorno={false}
        posicion={[Math.cos(a) * rr, 0, Math.sin(a) * rr]} rotacion={[0, Math.PI / 2 - a, 0]} />
    );
  });

  // Chispas en el punto de contacto mientras graba
  const chispas = grabando
    ? Array.from({length: 9}, (_, i) => {
        const h = Math.sin(i * 12.9898) * 43758.5453;
        const r = h - Math.floor(h);
        const t = ((frame + i * 5) % 14) / 14;
        const lado = (r - 0.5) * 0.5;
        const p: [number, number, number] = [
          c.pos[0] + afuera[0] * (0.04 + t * 0.32) + Math.cos(g) * 0 + Math.sin(g) * lado * t,
          c.pos[1] + (0.05 + r * 0.25) * t - t * t * 0.2,
          c.pos[2] + afuera[2] * (0.04 + t * 0.32) + Math.cos(g) * lado * t,
        ];
        return <Brillo key={i} posicion={p} color={i % 2 ? '#FFF3C4' : extra} radio={0.012 * (1 - t) + 0.004} />;
      })
    : null;

  // Camino de los rodillos alrededor del canto (línea discontinua en el plano de la moneda)
  const centro: [number, number, number] = [0, TOP + R, 0.15];
  const enCirculo = (th: number, rad: number): [number, number, number] => [
    centro[0] + rad * Math.cos(th) * afuera[0],
    centro[1] + rad * Math.sin(th),
    centro[2] + rad * Math.cos(th) * afuera[2],
  ];
  const camino = aparecer(frame, tBorde, 14) * interpolate(frame, [tRanuras + 12, tRanuras + 24], [1, 0], CL);
  const tramos = 28;
  const pasoArco = (Math.PI * 1.6) / tramos;
  const arco: React.ReactNode[] = [];
  for (let i = 0; i < tramos; i += 2) {
    if (i / tramos > camino) break;
    const th = -0.8 * Math.PI * 0 + 0.15 + i * pasoArco - Math.PI * 0.8 + Math.PI * 0.8 * 0;
    arco.push(<Linea key={i} desde={enCirculo(th - 0.0, R + 0.07)} hasta={enCirculo(th + pasoArco * 0.8, R + 0.07)} grosor={0.009} color={extra} />);
  }

  // Flecha que señala el borde
  const flecha = interpolate(frame, [tBorde, tBorde + 10], [0, 1], CL) * interpolate(frame, [tRanuras + 10, tRanuras + 20], [1, 0], CL);
  const puntoBorde = enCirculo(0.75, R + 0.03);

  // Etiqueta de las ranuras (señala la parte alta del canto, a un lado)
  const etiqueta = aparecer(frame, tRanuras, 8) * interpolate(frame, [fin - 6, fin], [1, 0], CL);
  const puntoRanuras = enCirculo(0.55, R + 0.01);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['moneda', 'cantoliso', 'balanza', 'fila', 'monedaintacta']} />

      {/* Fondo: la balanza se va de un salto */}
      <Pivote en={[-0.82, TOP, -0.2]} s={sBalanza} dy={(1 - sBalanza) * 0.35}>
        <Balanza paleta={paleta} frame={frame} paso={6} />
      </Pivote>

      {/* Delante: la fila raspada y la moneda intacta también se van */}
      <Pivote en={[-0.42, TOP, 0.72]} s={sFila} dy={(1 - sFila) * 0.25}>
        <Fila paleta={paleta} frame={frame} paso={6} />
      </Pivote>
      <Pivote en={[0.3, TOP, 0.7]} s={sIntacta} dy={(1 - sIntacta) * 0.25}>
        <MonedaIntacta paleta={paleta} frame={frame} paso={6} />
      </Pivote>

      {/* Medio: la moneda protagonista, recuñada y con su canto nuevo */}
      <Pivote en={[0, TOP, 0.15]} s={k} dy={saltito}>
        <Moneda paleta={paleta} frame={frame} paso={7} />
        {listo ? (
          <CantoEstriado paleta={paleta} frame={frame} paso={7} raspado={0} resaltado={ranurasResaltadas} />
        ) : (
          <>
            <CantoLiso paleta={paleta} frame={frame} paso={7} />
            <group position={centro} rotation={[0, g, 0]}>
              <group rotation={[Math.PI / 2, 0, 0]}>{ranuras}</group>
            </group>
          </>
        )}
      </Pivote>

      {/* La máquina de rodillos que graba el canto */}
      {sRod > 0.001 ? (
        <group position={[afuera[0] * dist + vibra, arriba + vibra, afuera[2] * dist]}>
          <Pivote en={c.pos} s={sRod}>
            <Rodillos paleta={paleta} frame={giroRodillo} paso={7} resaltado={rodResaltado} />
          </Pivote>
        </group>
      ) : null}
      {chispas}

      {/* Camino del grabado y flecha al borde */}
      {arco}
      <Flecha desde={[puntoBorde[0] - 0.42, puntoBorde[1] + 0.42, puntoBorde[2] + 0.2]} hasta={puntoBorde} color={extra} grosor={0.025} progreso={flecha} />

      {/* Rótulo: las ranuras */}
      <Etiqueta texto="ranuras" punto={puntoRanuras} desplazamiento={[-0.42, 0.5, 0.15]} escala={etiqueta} color={resalte} alto={0.17} />
    </group>
  );
};

escenas.Escena8:
import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Flecha, Linea, Brillo, caer, aparecer, rebote, flotar, mover, momento} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, Newton, CantoEstriado, FranjaRaspada, puntoCanto, TOP} from './Mundo';

export const Escena8: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, resalte, mostaza] = paleta.acentos;

  // Golpes sincronizados con la voz
  const tIsaac = momento(palabras, fps, 'Isaac', 1);
  const tNewton = momento(palabras, fps, 'Newton', 10);
  const tDirige = momento(palabras, fps, 'dirigía', 20);
  const tCasa = momento(palabras, fps, 'Casa', 44);
  const tMoneda = momento(palabras, fps, 'Moneda', 60);
  const tInglesa = momento(palabras, fps, 'inglesa', 70);
  const tLucha = momento(palabras, fps, 'lucha', 99);
  const fin = duracion;

  const canto = puntoCanto(8).pos;
  const sumar = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];

  // 1) La flecha roja de la escena anterior se retira (primer golpe)
  const flechaRoja = mover(frame, [tIsaac + 1, tIsaac + 12], [1, 0]);

  // 2) El busto de Newton cae sobre la mesa
  const NX = -0.78;
  const NZ = -0.3;
  const bajada = caer(frame, fps, tNewton, 1.6);
  const salto = rebote(frame, fps, tNewton + 2);
  const aplastar = frame > tNewton ? 1 - Math.exp(-(frame - tNewton) / 4) * Math.sin((frame - tNewton) / 1.5) * 0.12 : 1;
  const newtonResaltado = frame >= tNewton && frame < tNewton + 38;
  const balanceoBusto = flotar(frame, 0.04, 70) * aparecer(frame, tCasa, 10);

  // Polvo al aterrizar
  const polvoT = frame - tNewton;
  const polvo = polvoT >= 0 && polvoT < 14 ? polvoT / 14 : -1;

  // 3) Resaltes de la moneda y del canto
  const monedaResaltada = frame >= tMoneda && frame < tMoneda + 34;
  const raspado = mover(frame, [tLucha, tLucha + 14], [1, 0]);
  const cantoResaltado = frame >= tLucha && frame < tLucha + 30;
  const verFranja = frame < tLucha + 8;

  // 4) Línea punteada: Newton vigila la moneda
  const vigila = mover(frame, [tInglesa, tInglesa + 12], [0, 1]) * mover(frame, [fin - 12, fin - 3], [1, 0]);
  const cabeza: V3 = [NX + 0.05, TOP + 0.62, NZ + 0.08];

  // Flecha de mostaza: "dirige" (del busto hacia la moneda), en Casa
  const dirige = mover(frame, [tCasa, tCasa + 10], [0, 1]) * mover(frame, [tInglesa - 2, tInglesa + 6], [1, 0]);

  // Etiqueta del rótulo
  const etiqueta = aparecer(frame, tDirige, 8) * mover(frame, [fin - 12, fin - 3], [1, 0]);

  // Chispas cuando las ranuras vuelven
  const chispaT = frame - tLucha;
  const chispas =
    chispaT >= 0 && chispaT < 22
      ? Array.from({length: 7}, (_, i) => {
          const a = (i / 7) * Math.PI * 2;
          const r = 0.06 + chispaT * 0.012;
          const p: V3 = [canto[0] - 0.05 - Math.abs(Math.cos(a)) * r * 0.6, canto[1] + Math.sin(a) * r + chispaT * 0.006, canto[2] + Math.cos(a) * r];
          return <Brillo key={i} posicion={p} color={i % 2 ? '#FFFFFF' : resalte} radio={0.018 * (1 - chispaT / 22)} />;
        })
      : null;

  return (
    <group>
      {/* Base: el mundo del paso 8, sin las partes que animo yo */}
      <Mundo
        paso={8}
        frame={frame}
        fps={fps}
        paleta={paleta}
        ocultar={['cantoestriado', 'franjaraspada']}
        resaltar={monedaResaltada ? ['moneda'] : []}
      />

      {/* Canto estriado: las rayas vuelven al final */}
      <CantoEstriado paleta={paleta} paso={8} frame={frame} raspado={raspado} resaltado={cantoResaltado} />
      {verFranja ? <FranjaRaspada paleta={paleta} paso={8} frame={frame} /> : null}
      {chispas}

      {/* Flecha roja que señalaba la franja (viene de la escena anterior) */}
      <Flecha desde={sumar(canto, [-0.45, 0.28, 0.3])} hasta={sumar(canto, [-0.05, 0.02, 0.03])} color={rojo} grosor={0.03} progreso={flechaRoja} />

      {/* Busto de Newton que cae sobre su pedestal */}
      <group position={[NX, TOP + bajada.y + 0.03 * salto, NZ]} rotation={[0, balanceoBusto, bajada.giro * 0.4]} scale={[bajada.escala, bajada.escala * aplastar, bajada.escala]}>
        <group position={[-NX, -TOP, -NZ]}>
          <Newton paleta={paleta} frame={frame} paso={9} resaltado={newtonResaltado} />
        </group>
      </group>

      {/* Polvo del aterrizaje */}
      {polvo >= 0
        ? [0, 1, 2, 3, 4, 5].map((i) => {
            const a = (i / 6) * Math.PI * 2 + 0.3;
            const r = 0.18 + polvo * 0.16;
            return (
              <Pieza key={i} forma="esfera" medidas={[0.035]} color={crema} contorno={false}
                posicion={[NX + Math.cos(a) * r, TOP + 0.03 + polvo * 0.05, NZ + Math.sin(a) * r]}
                escala={0.4 + (1 - polvo) * 0.8} opacidad={1 - polvo} />
            );
          })
        : null}

      {/* Newton dirige: flecha del busto a la moneda */}
      <Flecha desde={[NX + 0.22, TOP + 0.45, NZ + 0.2]} hasta={sumar(canto, [-0.12, 0.08, -0.05])} color={mostaza} grosor={0.022} progreso={dirige} />

      {/* Newton vigila: línea punteada de la mirada hasta el canto */}
      {vigila > 0.01 ? (
        <Linea desde={cabeza} hasta={sumar(canto, [-0.06, 0.04, 0])} grosor={0.009} color={mostaza} progreso={vigila} discontinua />
      ) : null}

      {/* Rótulo */}
      <Etiqueta texto="isaac newton" punto={[NX, TOP + 0.72, NZ]} desplazamiento={[0.12, 0.5, 0.3]} escala={etiqueta} />
    </group>
  );
};

