import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Flecha, Brillo, Linea, aparecer, mover, momento, flotar} from '../lib3d';
import type {V3} from '../lib3d';
import {Mundo, CantoEstriado, FranjaRaspada, Lima, Mano, puntoCanto, poseMoneda, TOP, R} from './Mundo';

const PASO = 7;

// Escala un grupo alrededor de un punto del mundo (para que no se desplace al crecer/encoger).
const EnPunto: React.FC<{p: V3; s: number; children: React.ReactNode}> = ({p, s, children}) => {
  if (s <= 0.001) return null;
  return (
    <group position={p} scale={s}>
      <group position={[-p[0], -p[1], -p[2]]}>{children}</group>
    </group>
  );
};

export const Escena7: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, resalte, mostaza] = paleta.acentos;

  // Golpes sincronizados con la voz
  const tRaspas = momento(palabras, fps, 'raspas', 7);
  const tRayas = momento(palabras, fps, 'rayas', 38);
  const tBorran = momento(palabras, fps, 'borran', 54);
  const tTrampa = momento(palabras, fps, 'trampa', 77);
  const tNota = momento(palabras, fps, 'nota', 93);
  const fin = duracion;

  // Geometría del canto que mira a la cámara
  const c = puntoCanto(PASO);
  const cp = c.pos;
  const g = c.giro;
  const afuera: V3 = [-Math.cos(g), 0, Math.sin(g)];
  const normal: V3 = [Math.sin(g), 0, Math.cos(g)];
  const pose = poseMoneda(PASO);
  const arribaCanto: V3 = [pose.x, pose.y + R, pose.z];

  // Limado: la lima sube y baja por el canto desde el fotograma 0
  const limando = 1 - mover(frame, [tBorran + 4, tBorran + 10], [0, 1]);
  const vaiven = Math.sin(frame / 2.1) * 0.055 * limando * (0.6 + 0.4 * aparecer(frame, tRaspas, 4));
  const raspado = mover(frame, [tRaspas + 3, tBorran + 6], [0, 1]);
  const franja = mover(frame, [Math.round((tRaspas + tBorran) / 2), tBorran + 6], [0, 1]);

  // La mano se retira para dejar ver la trampa
  const salida = mover(frame, [tBorran + 6, tBorran + 18], [0, 1]);
  const manoEsc = 1 - salida;
  const manoOff: V3 = [afuera[0] * 0.5 * salida, vaiven + 0.7 * salida * salida, afuera[2] * 0.5 * salida];

  // Resaltes
  const rayasResalt = frame >= tRayas && frame < tRayas + 36;
  const franjaResalt = frame >= tTrampa && frame < tTrampa + 40;

  // Textos y flecha
  const cierre = 1 - mover(frame, [fin - 9, fin - 1], [0, 1]);
  const etRayas = aparecer(frame, tRayas, 8) * (1 - mover(frame, [tTrampa - 6, tTrampa], [0, 1]));
  const etTrampa = aparecer(frame, tTrampa + 2, 8) * cierre;
  const pulso = 1 + Math.sin(Math.max(0, frame - tNota) / 3) * 0.06 * aparecer(frame, tNota, 4);
  const colaF: V3 = [cp[0] + afuera[0] * 0.5, cp[1] + 0.32, cp[2] + afuera[2] * 0.5 + 0.1];
  const puntaF: V3 = [cp[0] + afuera[0] * 0.05, cp[1] + 0.03, cp[2] + afuera[2] * 0.05 + 0.01];
  const flecha = mover(frame, [tTrampa, tTrampa + 9], [0, 1]) * cierre;

  // Limaduras plateadas que caen mientras se lima
  const limaduras = Array.from({length: 12}, (_, i) => {
    const per = 16;
    const t = ((frame + i * 3.7) % per) / per;
    const lado = Math.sin(i * 7.31) * 0.05;
    const caida = (cp[1] - TOP - 0.01) * t * t;
    const p: V3 = [
      cp[0] + afuera[0] * (0.02 + t * 0.12) + normal[0] * lado,
      cp[1] + vaiven * 0.5 - caida,
      cp[2] + afuera[2] * (0.02 + t * 0.12) + normal[2] * lado,
    ];
    return {p, vis: limando * (t < 0.95 ? 1 : 0)};
  });
  // Montoncito de polvillo que crece sobre la mesa
  const monton = mover(frame, [tRaspas, tBorran + 6], [0.2, 1]);
  const montonPos: V3 = [cp[0] + afuera[0] * 0.13, TOP + 0.003, cp[2] + afuera[2] * 0.13];

  // Destello de "golpe" al aparecer la franja lisa
  const destello = aparecer(frame, tBorran, 4) * (1 - mover(frame, [tBorran + 4, tBorran + 14], [0, 1]));

  return (
    <group>
      {/* Mundo base: taller y moneda estriada (el canto lo animamos nosotros) */}
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['cantoestriado']} resaltar={[]} />

      {/* Canto con ranuras: las estrías de la franja se van borrando */}
      <CantoEstriado paleta={paleta} paso={PASO} raspado={raspado} resaltado={rayasResalt} frame={frame} />

      {/* La franja lisa y fea que deja el raspado */}
      <EnPunto p={cp} s={franja * (franjaResalt ? pulso : 1)}>
        <FranjaRaspada paleta={paleta} paso={PASO + 1} resaltado={franjaResalt} frame={frame} />
      </EnPunto>
      {destello > 0.01 ? (
        <Brillo posicion={[cp[0] + afuera[0] * 0.03, cp[1], cp[2] + afuera[2] * 0.03]} color="#FFFFFF" radio={0.05 * destello} />
      ) : null}

      {/* La misma mano con la lima, limando y luego retirándose */}
      <group position={manoOff}>
        <EnPunto p={cp} s={manoEsc}>
          <Lima paleta={paleta} paso={PASO} frame={frame} />
          <Mano paleta={paleta} paso={PASO} frame={frame} />
        </EnPunto>
      </group>

      {/* Limaduras que caen y polvillo en la mesa */}
      {limaduras.map((l, i) =>
        l.vis > 0.01 ? (
          <Pieza key={i} forma="esfera" medidas={[0.007 + (i % 3) * 0.003]} color={i % 2 ? '#EEF2F6' : '#C9CFD7'} contorno={false} posicion={l.p} />
        ) : null,
      )}
      <group position={montonPos} scale={[monton, monton, monton]}>
        <Pieza forma="media_esfera" medidas={[0.045]} color="#C9CFD7" escala={[1, 0.3, 1]} />
        {[0, 1, 2, 3, 4].map((i) => (
          <Pieza key={i} forma="esfera" medidas={[0.007]} color="#EEF2F6" contorno={false}
            posicion={[Math.cos(i * 1.3) * 0.06, 0.004, Math.sin(i * 1.3) * 0.05]} />
        ))}
        <Brillo posicion={[0, 0.02 + flotar(frame, 0.004, 40), 0]} color="#FFFFFF" radio={0.008} />
      </group>

      {/* Guía discontinua del recorrido de la lima mientras raspa */}
      <Linea
        desde={[cp[0] + afuera[0] * 0.06, cp[1] - 0.16, cp[2] + afuera[2] * 0.06]}
        hasta={[cp[0] + afuera[0] * 0.06, cp[1] + 0.16, cp[2] + afuera[2] * 0.06]}
        grosor={0.006}
        color={mostaza}
        discontinua
        progreso={limando * aparecer(frame, tRaspas, 8)}
      />

      {/* Flecha roja que señala la franja raspada */}
      <Flecha desde={colaF} hasta={puntaF} color={rojo} grosor={0.03} progreso={flecha} />

      {/* Etiquetas (como mucho dos a la vez, a los lados) */}
      <Etiqueta texto="rayas" punto={[arribaCanto[0] + 0.05, arribaCanto[1] - 0.02, arribaCanto[2]]} desplazamiento={[0.5, 0.35, 0.15]} escala={etRayas} />
      <Etiqueta texto="trampa" punto={[cp[0] + afuera[0] * 0.03, cp[1] - 0.1, cp[2] + afuera[2] * 0.03]} desplazamiento={[-0.32, -0.3, 0.2]} escala={etTrampa} color={resalte} />

      {/* Capa delantera: una moneda chica caída en primer plano */}
      <group position={[0.55, TOP, 0.78]} rotation={[0, 0.4, 0]}>
        <Pieza forma="cilindro" medidas={[0.08, 0.08, 0.022, 32]} color="#C9CFD7" posicion={[0, 0.011, 0]} />
        <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.005]} color={crema} posicion={[0, 0.024, 0]} contorno={false} />
      </group>
    </group>
  );
};
